public class PersonalizationJobConfiguration : IEntityTypeConfiguration<PersonalizationJob>
{
    /// <summary>
    /// PersonalizationJob varligi icin tablo adi, birincil anahtar, alan kisitlari, index ve
    /// iliskileri yapilandirir.
    /// </summary>
    public void Configure(EntityTypeBuilder<PersonalizationJob> builder)
    {
        // Tablo adini belirtir.
        builder.ToTable("PersonalizationJob", "profile");

        // Birincil anahtari tanimlar.
        builder.HasKey(x => x.Id);

        // Isin guncel durumu.
        builder.Property(x => x.Status)
