        // Kullanici basina kuyruktaki/islenen isleri hizli sorgulayabilmek icin index.
        builder.HasIndex(x => x.UserId);

        // Ayni anda ayni kullanici icin birden fazla bekleyen/islenen (henuz sonuclanmamis)
        // is olusmasini engellemek amacli sorgularda kullanilacak birlesik index.
        builder.HasIndex(x => new { x.UserId, x.Status });

